In C, the best way to return an error is by using a combination of return codes and possibly a global variable or a struct to pass additional error information. Here's a simple example using return codes:

```c
#include <stdio.h>

#define SUCCESS 0
#define ERROR_OUT_OF_MEMORY -1
#define ERROR_INVALID_INPUT -2

int myFunction() {
    // Your code here
    // If an error occurs, return the appropriate error code
    if (/* error condition */) {
        return ERROR_OUT_OF_MEMORY;
    }
    // If everything is fine, return success
    return SUCCESS;
}

int main() {
    int result = myFunction();
    if (result == SUCCESS) {
        printf("Function executed successfully.\n");
    } else if (result == ERROR_OUT_OF_MEMORY) {
        printf("Error: Out of memory.\n");
    } else if (result == ERROR_INVALID_INPUT) {
        printf("Error: Invalid input.\n");
    }
    // Handle other errors as needed
    return 0;
}
```

In this example, `myFunction` returns an integer that indicates the success or failure of the function. The `main` function checks the return value and handles the error accordingly. This is a simple and widely used pattern in C for error handling. For more complex scenarios, you might want to use a struct to pass additional error information, such as a message or an error code. Here's an example of that approach:

```c
#include <stdio.h>
#include <string.h>

typedef struct {
    int code;
    char message[256];
} ErrorInfo;

ErrorInfo myFunction() {
    ErrorInfo error;
    // Your code here
    // If an error occurs, set the error code and message
    if (/* error condition */) {
        error.code = ERROR_OUT_OF_MEMORY;
        strncpy(error.message, "Out of memory.", sizeof(error.message));
        return error;
    }
    // If everything is fine, return an error info with a success code
    error.code = SUCCESS;
    return error;
}

int main() {
    ErrorInfo result = myFunction();
    if (result.code == SUCCESS) {
        printf("Function executed successfully.\n");
    } else {
        printf("Error %d: %s\n", result.code, result.message);
    }
    return 0;
}
```

